import{_ as e,a as t,c as r,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"自动化任务：基础对象与机制","description":"按 任务参数、批次键、身份、幂等、锁与调度时钟 的实际关系组织。","frontmatter":{"title":"自动化任务：基础对象与机制","description":"按 任务参数、批次键、身份、幂等、锁与调度时钟 的实际关系组织。","showdocs":{"topics":[{"id":"automation","title":"定时任务与自动化","link":"/topics/automation/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"自动化对象与任务理论课程","summary":"按 任务参数、批次键、身份、幂等、锁与调度时钟 的实际关系组织。","status":"active","related":[{"title":"自动化：按日期生成可重放报告","link":"/systems/shell-automation/automation/plus/practice/application","kind":"完整实践","scope":"general","audience":"general"},{"title":"自动化任务：发布、排障与恢复练习","link":"/systems/shell-automation/automation/operations","kind":"知识专题","scope":"general","audience":"general"}],"prev":false,"next":{"text":"自动化：按日期生成可重放报告","link":"/systems/shell-automation/automation/plus/practice/application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"自动化：按日期生成可重放报告","link":"/systems/shell-automation/automation/plus/practice/application"}},"headers":[],"relativePath":"systems/shell-automation/automation/task-contract.md","filePath":"systems/shell-automation/automation/task-contract.md"}'),n={name:"systems/shell-automation/automation/task-contract.md"};function i(l,a,s,c,p,h){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="自动化任务-基础对象与机制" tabindex="-1">自动化任务：基础对象与机制 <a class="header-anchor" href="#自动化任务-基础对象与机制" aria-label="Permalink to &quot;自动化任务：基础对象与机制&quot;">​</a></h1><h2 id="part-1" tabindex="-1">任务参数、批次与执行身份 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;任务参数、批次与执行身份 {#part-1}&quot;">​</a></h2><p>定时任务的可靠性由触发、执行和提交共同决定。先明确批次时区、输入输出与执行账户，再设计互斥和幂等；调度器报告已启动，不能证明业务产物已经完成。</p><h3 id="part-1-contract" tabindex="-1">自动化不是定时器本身 <a class="header-anchor" href="#part-1-contract" aria-label="Permalink to &quot;自动化不是定时器本身 {#part-1-contract}&quot;">​</a></h3><p>自动化 任务契约先明确输入、输出、身份和副作用，再选择触发器。Shell语言执行逻辑、操作系统提供权限和资源、调度器决定何时调用；三者职责不能混合。准备阶段只读取现有Python3.12脚本与配置，不安装依赖、不注册cron、LaunchAgent或计划任务。</p><h3 id="part-1-commands" tabindex="-1">参数与工作目录 <a class="header-anchor" href="#part-1-commands" aria-label="Permalink to &quot;参数与工作目录 {#part-1-commands}&quot;">​</a></h3><p>自动化 参数应显式给出批次日期与固定根目录，不依赖调度器的当前工作目录。命令使用绝对程序路径和分开的参数；路径带空格不意味着需拼接成可执行字符串。示例根目录由脚本所在目录确定，日期采用 <code>YYYY-MM-DD</code>，不能通过参数指定任意输出路径。</p><h3 id="part-1-identity" tabindex="-1">最小身份与秘密边界 <a class="header-anchor" href="#part-1-identity" aria-label="Permalink to &quot;最小身份与秘密边界 {#part-1-identity}&quot;">​</a></h3><p>自动化 身份决定能读取哪些输入和写入哪些产物，调度账户不应默认等于交互登录用户。示例只在自身专用目录写文件，要求目录由运行者拥有且父目录不可被不可信用户改写；不使用管理员或云凭据。配置和日志都不放口令，日志中的用户名和路径也需按受众处理。</p><h3 id="part-1-evidence" tabindex="-1">成功契约与证据 <a class="header-anchor" href="#part-1-evidence" aria-label="Permalink to &quot;成功契约与证据 {#part-1-evidence}&quot;">​</a></h3><p>自动化 成功不等于触发器显示已运行。需要进程退出码、批次标识与最终产物三者一致；定时器本身可能成功启动了一个随后失败的程序。示例成功输出 created 或 unchanged，最终报告内容与指定日期一致；失败返回非零且不把锁目录当成功标记。</p><h3 id="part-1-exercise" tabindex="-1">练习与参考解答 <a class="header-anchor" href="#part-1-exercise" aria-label="Permalink to &quot;练习与参考解答 {#part-1-exercise}&quot;">​</a></h3><p>题目：机器本地时区刚跨午夜，调度器传入2026-10-17，系统当前日期已是2026-10-18。示例应写哪个文件、报告日期是什么？是否需要按当前日期改写参数？</p><p>参考解答：以显式批次参数为准，目标是state/report-2026-10-17.json，batchDate为2026-10-17。不能静默改成当前日，否则补跑旧批次会写错幂等键。调度器负责按约定时区选择批次，脚本只验证ISO日期并处理该键；成功证据应同时核对退出0、created/unchanged日期及目标文件内容。</p><h3 id="part-1-sources" tabindex="-1">核对资料 <a class="header-anchor" href="#part-1-sources" aria-label="Permalink to &quot;核对资料 {#part-1-sources}&quot;">​</a></h3><ul><li><a href="https://learn.microsoft.com/en-us/windows/win32/taskschd/taskschedulerschema-multipleinstancespolicy-settingstype-element" target="_blank" rel="noopener noreferrer">Microsoft 多实例策略</a></li><li><a href="https://developer.apple.com/library/archive/documentation/MacOSX/Conceptual/BPSystemStartup/Chapters/CreatingLaunchdJobs.html" target="_blank" rel="noopener noreferrer">Apple launchd 周期作业</a></li><li><a href="https://docs.python.org/3.12/library/time.html" target="_blank" rel="noopener noreferrer">Python 3.12 时间</a></li><li><a href="https://docs.python.org/3.12/library/os.html" target="_blank" rel="noopener noreferrer">Python 3.12 os 文件接口</a></li></ul><h2 id="part-2" tabindex="-1">调度、幂等、互斥与提交 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;调度、幂等、互斥与提交 {#part-2}&quot;">​</a></h2><p>先明确批次日期、专用 state 目录与执行身份，再对照<a href="/systems/shell-automation/automation/plus/practice/application#source">配套示例</a>理解锁、created/unchanged、退出码和最终报告。</p><p>教学版本族：Python 3.12 标准库；cron 常见五字段模型、launchd 与 Windows Task Scheduler 2.0 仅讲调度语义，不注册或运行任务。核对日期2026-10-17，不称为2026最新版。示例未执行，配置与命令需按目标环境验收。</p><h3 id="part-2-idempotence" tabindex="-1">幂等键与内容一致 <a class="header-anchor" href="#part-2-idempotence" aria-label="Permalink to &quot;幂等键与内容一致 {#part-2-idempotence}&quot;">​</a></h3><p>自动化 幂等是重复同一批次后最终效果相同，不是简单忽略文件存在。日期是本例幂等键，相同日期产生完全相同JSON内容；已有目标内容一致返回 unchanged，不一致返回冲突而不覆盖。真实副作用如发邮件或付款不能靠本地文件标记实现exactly-once。</p><h3 id="part-2-reentry" tabindex="-1">重入互斥与过期锁 <a class="header-anchor" href="#part-2-reentry" aria-label="Permalink to &quot;重入互斥与过期锁 {#part-2-reentry}&quot;">​</a></h3><p>自动化 重入需要任务自身互斥，因为人工调用和多个调度器可能绕开单个调度器策略。本例用原子 mkdir 获取固定锁，已存在退出3，不按时间自动删除锁。进程被强杀可能留下锁，恢复时必须先确认没有存活实例；仅凭mtime很旧不能证明可抢占。</p><h3 id="part-2-clock" tabindex="-1">墙钟、时区与补跑 <a class="header-anchor" href="#part-2-clock" aria-label="Permalink to &quot;墙钟、时区与补跑 {#part-2-clock}&quot;">​</a></h3><p>自动化 时钟要区分墙钟日历与单调耗时。夏令时、时区调整、休眠与关机可能导致重复或漏触发；cron五字段不自带历史批次账本。示例显式传入日期，不从“当前时间减24小时”猜业务日，因而可重放漏掉的具体批次。任务耗时日后可用单调时钟度量，不用本地墙钟相减下结论。</p><h3 id="part-2-scheduler" tabindex="-1">触发器与并发策略 <a class="header-anchor" href="#part-2-scheduler" aria-label="Permalink to &quot;触发器与并发策略 {#part-2-scheduler}&quot;">​</a></h3><p>自动化 调度比较：Windows MultipleInstancesPolicy 的 IgnoreNew 忽略已有实例期间的新实例，Queue排队，Parallel并发，StopExisting停止旧实例；这些不等同跨任务全局锁。launchd 的 interval 与日历触发也不同，不应承诺睡眠后补齐每一次遗漏。用户会话、工作目录和环境必须单独记录，本例不交付自动启用的调度配置。</p><h3 id="part-2-exercise" tabindex="-1">练习与参考解答 <a class="header-anchor" href="#part-2-exercise" aria-label="Permalink to &quot;练习与参考解答 {#part-2-exercise}&quot;">​</a></h3><p>题目：同日期任务A已获取.lock，手工启动B；A完成replace后在打印created之前被强杀。B第一次及人工确认A已退出、移除空锁后的重跑分别应得到什么？</p><p>参考解答：B第一次获取mkdir锁失败，退出3，不能按时间自动抢锁。A强杀可能留下.lock，但最终报告已发布；确认无活跃实例并保留证据后，人工仅移除该空锁。再次同日期重跑比较确定内容，应输出unchanged并退出0，而不是生成第二份报告。调度器IgnoreNew无法阻止独立手工B，所以任务自身互斥仍必要。</p><h3 id="part-2-sources" tabindex="-1">核对资料 <a class="header-anchor" href="#part-2-sources" aria-label="Permalink to &quot;核对资料 {#part-2-sources}&quot;">​</a></h3><p>本节沿用<a href="#part-1-sources">本页资料与示例入口</a>。</p>',32)])])}const m=e(n,[["render",i]]);export{u as __pageData,m as default};
